import 'package:flutter/material.dart'; import '../models/user.dart'; import '../services/api.dart'; import '../services/update_service.dart'; import 'login.dart'; import 'feed.dart'; import 'communities.dart'; import 'people.dart'; import 'profile.dart';
class Home extends StatefulWidget{final User user;const Home({super.key,required this.user});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{int i=0;late final List<Widget> pages;@override void initState(){super.initState();pages=[Feed(user:widget.user),Communities(user:widget.user),People(user:widget.user),Profile(user:widget.user)];WidgetsBinding.instance.addPostFrameCallback((_)=>UpdateService.check(context));}Future<void> logout()async{await Api.logout();if(!mounted)return;Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>const Login()),(_)=>false);}@override Widget build(BuildContext c)=>Scaffold(body:pages[i],bottomNavigationBar:NavigationBar(selectedIndex:i,onDestinationSelected:(v)=>setState(()=>i=v),destinations:const[NavigationDestination(icon:Icon(Icons.auto_awesome_outlined),selectedIcon:Icon(Icons.auto_awesome),label:'Home'),NavigationDestination(icon:Icon(Icons.groups_outlined),selectedIcon:Icon(Icons.groups),label:'Communities'),NavigationDestination(icon:Icon(Icons.people_outline),selectedIcon:Icon(Icons.people),label:'People'),NavigationDestination(icon:Icon(Icons.person_outline),selectedIcon:Icon(Icons.person),label:'Profile')]));}
